using Hook = std::function<bool(Event&)>;

class Dispatcher {
  std::vector<std::pair<std::string, Hook>> hooks_;
 public:
  Registration add(std::string event, Hook hook);   // RAII: unregisters on destruction
  void fire(Event& e) {
    for (auto& [name, hook] : hooks_)
      if (name == e.name && !hook(e)) return;        // veto stops the chain
  }
};

